package com.rotarypumpers.meraki;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import org.json.*;
/** Small normalized JPEG assets stay on the phone; portable recipe backups include them. */
final class RecipeMediaStore {
 static final int MAX_BYTES=96*1024,MAX_BACKUP_BYTES=32*1024*1024;private final File dir;
 RecipeMediaStore(File files){dir=new File(files,"recipe-media-v1");}
 static boolean valid(String id){return id!=null&&id.matches("[a-f0-9]{64}");}
 static String digest(byte[] data)throws Exception{StringBuilder b=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(data))b.append(String.format(Locale.US,"%02x",x&255));return b.toString();}
 static void jpeg(byte[] bytes)throws IOException{if(bytes.length<4||bytes.length>MAX_BYTES||(bytes[0]&255)!=255||(bytes[1]&255)!=216||(bytes[bytes.length-2]&255)!=255||(bytes[bytes.length-1]&255)!=217)throw new IOException("Invalid or oversized product photo");}
 synchronized String put(byte[] bytes)throws Exception{jpeg(bytes);String id=digest(bytes);if(!dir.exists()&&!dir.mkdirs())throw new IOException("Cannot save product photo");File dest=file(id);if(dest.isFile()){if(!Arrays.equals(read(id),bytes))throw new IOException("Product photo checksum mismatch");return id;}File tmp=File.createTempFile("incoming-",".tmp",dir);try{try(FileOutputStream out=new FileOutputStream(tmp)){out.write(bytes);out.getFD().sync();}Files.move(tmp.toPath(),dest.toPath(),StandardCopyOption.ATOMIC_MOVE);}finally{tmp.delete();}return id;}
 File file(String id)throws IOException{if(!valid(id))throw new IOException("Invalid product photo reference");return new File(dir,id+".jpg");}
 synchronized byte[] read(String id)throws Exception{File f=file(id);if(!f.isFile()||f.length()>MAX_BYTES)throw new IOException("Product photo not available");byte[] b=Files.readAllBytes(f.toPath());jpeg(b);if(!digest(b).equals(id))throw new IOException("Product photo checksum mismatch");return b;}
 synchronized void addTo(JSONObject backup,JSONArray recipes)throws Exception{JSONObject photos=new JSONObject();for(int i=0;i<recipes.length();i++){String id=recipes.getJSONObject(i).optString("record_photo","");if(!id.isEmpty()&&!photos.has(id)){try{photos.put(id,Base64.getEncoder().encodeToString(read(id)));}catch(FileNotFoundException e){}}}if(photos.length()>0)backup.put("photos",photos);}
 synchronized void importFrom(JSONObject root)throws Exception{JSONObject photos=root.optJSONObject("photos");if(photos==null)return;if(photos.length()>200)throw new IOException("Too many product photos");Map<String,byte[]> checked=new LinkedHashMap<>();for(Iterator<String> it=photos.keys();it.hasNext();){String id=it.next();if(!valid(id))throw new IOException("Invalid product photo reference");String encoded=photos.getString(id);if(encoded.length()>MAX_BYTES*4/3+8)throw new IOException("Product photo too large");byte[] b;try{b=Base64.getDecoder().decode(encoded);}catch(IllegalArgumentException e){throw new IOException("Invalid product photo data");}jpeg(b);if(!digest(b).equals(id))throw new IOException("Product photo checksum mismatch");checked.put(id,b);}for(byte[] b:checked.values())put(b);}
}
